<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\WebAuthn\Infrastructure\Driven;

use DateTimeImmutable;
use Override;
use PDO;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\WebAuthnCredential;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\Gateway\WebAuthnCredentialGateway;

final class WebAuthnCredentialSqlAdapter implements WebAuthnCredentialGateway
{
    public function __construct(private readonly PDO $pdo)
    {
    }

    #[Override]
    public function store(WebAuthnCredential $credential): void
    {
        $stmt = $this->pdo->prepare(
            'INSERT INTO access_user_webauthn_credential
             (uid, tenant_id, user_uid, username, credential_id, public_key, sign_count,
              aaguid, device_name, transports_json, created_at, last_used_at, enabled)
             VALUES
             (:uid, :tenant_id, :user_uid, :username, :credential_id, :public_key, :sign_count,
              :aaguid, :device_name, :transports_json, :created_at, :last_used_at, :enabled)'
        );
        $stmt->bindValue('uid', $credential->uid);
        $stmt->bindValue('tenant_id', $credential->tenantId);
        $stmt->bindValue('user_uid', $credential->userUid);
        $stmt->bindValue('username', $credential->username);
        $stmt->bindValue('credential_id', $credential->credentialId);
        $stmt->bindValue('public_key', $credential->publicKey);
        $stmt->bindValue('sign_count', $credential->signCount, PDO::PARAM_INT);
        $stmt->bindValue('aaguid', $credential->aaguid);
        $stmt->bindValue('device_name', $credential->deviceName);
        $stmt->bindValue('transports_json', $credential->transports !== null ? json_encode($credential->transports) : null);
        $stmt->bindValue('created_at', $credential->createdAt->format('Y-m-d H:i:s'));
        $stmt->bindValue('last_used_at', $credential->lastUsedAt?->format('Y-m-d H:i:s'));
        $stmt->bindValue('enabled', $credential->enabled ? 1 : 0, PDO::PARAM_INT);
        $stmt->execute();
    }

    #[Override]
    public function findByCredentialId(string $credentialId, string $tenantId): ?WebAuthnCredential
    {
        $stmt = $this->pdo->prepare(
            'SELECT * FROM access_user_webauthn_credential
             WHERE credential_id = :credential_id AND tenant_id = :tenant_id AND enabled = 1'
        );
        $stmt->bindValue('credential_id', $credentialId);
        $stmt->bindValue('tenant_id', $tenantId);
        $stmt->execute();
        $row = $stmt->fetch(PDO::FETCH_ASSOC);
        return $row ? $this->mapRow($row) : null;
    }

    #[Override]
    public function findByUser(string $userUid, string $tenantId): array
    {
        $stmt = $this->pdo->prepare(
            'SELECT * FROM access_user_webauthn_credential
             WHERE user_uid = :user_uid AND tenant_id = :tenant_id AND enabled = 1
             ORDER BY created_at DESC'
        );
        $stmt->bindValue('user_uid', $userUid);
        $stmt->bindValue('tenant_id', $tenantId);
        $stmt->execute();
        return array_map([$this, 'mapRow'], $stmt->fetchAll(PDO::FETCH_ASSOC));
    }

    #[Override]
    public function updateSignCount(string $credentialId, string $tenantId, int $signCount, DateTimeImmutable $lastUsedAt): void
    {
        $stmt = $this->pdo->prepare(
            'UPDATE access_user_webauthn_credential
             SET sign_count = :sign_count, last_used_at = :last_used_at
             WHERE credential_id = :credential_id AND tenant_id = :tenant_id'
        );
        $stmt->bindValue('sign_count', $signCount, PDO::PARAM_INT);
        $stmt->bindValue('last_used_at', $lastUsedAt->format('Y-m-d H:i:s'));
        $stmt->bindValue('credential_id', $credentialId);
        $stmt->bindValue('tenant_id', $tenantId);
        $stmt->execute();
    }

    private function mapRow(array $row): WebAuthnCredential
    {
        $transports = null;
        if (!empty($row['transports_json'])) {
            $decoded = json_decode($row['transports_json'], true);
            $transports = is_array($decoded) ? $decoded : null;
        }
        return new WebAuthnCredential(
            uid: $row['uid'],
            tenantId: $row['tenant_id'],
            userUid: $row['user_uid'],
            username: $row['username'],
            credentialId: $row['credential_id'],
            publicKey: $row['public_key'],
            signCount: (int) $row['sign_count'],
            aaguid: $row['aaguid'] ?? null,
            deviceName: $row['device_name'] ?? null,
            transports: $transports,
            createdAt: new DateTimeImmutable($row['created_at']),
            lastUsedAt: isset($row['last_used_at']) ? new DateTimeImmutable($row['last_used_at']) : null,
            enabled: (bool) $row['enabled'],
        );
    }
}
